/// operational snapshot. Disarmed once the warm completes.
struct ClearPreparingOnDrop {
    signal: Option<Arc<std::sync::atomic::AtomicBool>>,
    pool_status: Option<Arc<preloop_observability::status::PoolStatus>>,
    armed: bool,
}

